ALTER TABLE public.v2_merchants ADD COLUMN IF NOT EXISTS current_deal_text TEXT, ADD COLUMN IF NOT EXISTS deal_expiry_time TIMESTAMPTZ, ADD COLUMN IF NOT EXISTS is_currently_available BOOLEAN DEFAULT false, ADD COLUMN IF NOT EXISTS community_upvotes INTEGER DEFAULT 0;
CREATE OR REPLACE FUNCTION deduct_v2_wallet(merchant_uuid UUID, amount DECIMAL) RETURNS BOOLEAN LANGUAGE plpgsql SECURITY DEFINER AS $$ DECLARE bal DECIMAL; BEGIN SELECT wallet_balance INTO bal FROM v2_merchants WHERE id=merchant_uuid; IF bal >= amount THEN UPDATE v2_merchants SET wallet_balance=wallet_balance-amount WHERE id=merchant_uuid; RETURN true; ELSE RETURN false; END IF; END; $$;
